pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint256 amount, uint48 blk) public {
        vm.assume(amount < 10 ether);
        vm.assume(blk % 15 == 0);
        vm.warp(1);
        vm.roll(blk);
        address sender = makeAddr("sender");
        vm.deal(sender, amount);
        vm.deal(address(c), 5 ether);
        vm.prank(sender);
        (bool ok,) = address(c).call{value: amount}("");
        assertTrue(!ok);
    }
}
